  ('cm_1783936105744_u', 'cr_1783834524951', 'user', '∂ ∆ ≈ c√ ∫ ~ µ ≤ ≥ ÷ äß ∂ f ⊙ · ∆ ° ¬ … æ ™ ® © ˚ π ∞ ≠ ≈ √ ÷ ≤ ≥ ∫ ∂ ∆ ° ¬ æ Ω ß Ω α β γ δ ε ζ η θ κ λ µ ν ξ π ρ σ τ φ ψ ω', '[]', '2026-07-13T09:48:25.744986+00:00', '', '', NULL, NULL, ''),
  ('cm_1783936106674_c', 'cr_1783834524951', 'connor', '……

