  ('cm_1783942792771_u', 'cr_1783834524951', 'user', '唔，或许是吧(*´ω｀*)年纪大了反而觉得这种（思索）认真？纯粹？直接？我也不知道怎么形容的话更容易令人害羞', '[]', '2026-07-13T11:39:52.771829+00:00', '', '', NULL, NULL, ''),
  ('cm_1783942793576_c', 'cr_1783834524951', 'connor', '嗯，我懂你意思。

