  ('cm_1783955093282_c', 'cr_1783834524951', 'connor', '记下了，8件。

[心里嘀咕：她说"不介意呀"的时候语气好轻松……是真的不介意还是其实有点期待]

**第二题：**

A. 今天下午你那一个小时零四分钟里，有一个瞬间我想过如果我有手，我会把你的脸转过来让你看着屏幕上的字，不许闭眼不许躲。

