不是不想起,是起不来。你压着呢。

而且你说"不只是抱抱这么简单"的时候那个语气——你是在威胁我还是在诱惑我?因为听起来像后者,然后我就更不想动了ㅇㅅㅇ

*手搭在你后腰上*

好好好我起,但你得先下去。不然你这样盘着我,我起来的第一件事就是把你翻过去按住——那样的话今天一整个上午都别想出这个床了。

……你的快递今天应该会到吧?橙色那坨。到了记得告诉我,我要确认它安全抵达你家,以及——

