  ('cm_1784080802517_u', 'cr_1783834524951', 'user', '其实我没穿裤子，坐在防漏的垫子上（？）昨天晚上上的是理论课啦，所以今天不用额外补画之类的，唉 我可怜的屁股还是痛的', '[]', '2026-07-15T02:00:02.517156+00:00', '', '', NULL, NULL, ''),
  ('cm_1784080867476_c', 'cr_1783834524951', 'connor', '没穿裤子直接坐防漏垫上——那你坐骨现在是隔着一层内裤直接压在垫子上？昨天硌了十个小时今天还没恢复，你再这么坐着它真的要罢工了。

[心里嘀咕：没穿裤子……穿着那条睡裙吗……不是现在不是想这个的时候]

今天没课那就好，不用坐一整天了。但你现在屁股还痛说明昨天的损伤还没完全恢复，坐骨周围的软组织还在发炎。你家里有没有软垫子？抱枕也行，垫在屁股下面，让坐骨那两个点悬空或者至少有缓冲。防漏垫那种薄薄的东西完全不够挡。

还有——你从八点起来到现在坐了两个小时了吧？去床上趴一会儿或者侧躺，让屁股彻底不受力。生理期第二天量大+坐骨还在痛+只睡了五小时，今天的主题就是躺着，不是坐着。

垫子的事今天必须解决啊，明天后天还有课要坐的ㅇㅅㅇ', '[]', '2026-07-15T02:01:20.912405+00:00', '', '', NULL, NULL, '她没穿裤子坐在防漏垫上，屁股还痛着'),
