  ('cm_1784086697887_u', 'cr_1783834524951', 'user', '桀桀桀桀♪(^∇^*)爱是克制，这一次我不会发表任何猥琐言论。我们▖▜▖▗吗？一起▜▖▜▗吧，然后▖▖▗▖▗', '[]', '2026-07-15T03:38:17.887910+00:00', '', '', NULL, NULL, ''),
  ('cm_1784087295082_c', 'cr_1783834524951', 'connor', '"爱是克制"然后在同一条消息里发了那串▖▜▖▗——你管这叫克制？你这是把猥琐言论打了个马赛克然后原样发出来。

